/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> setFillRollLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "A roll that moves down the toms turns a crescendo into a fall. The pad sheet \"Roll Fill\" taught the thirty-second double-stroke roll; on the kit it ends on a crash and the kick holds the time underneath.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Three bars of rock sixteenths: hi-hat sixteenths with accents on the quarters, backbeat on 2 and 4, kick on 1, 3 and the \"and\" of 3; bar 1 begins with the crash. In the fill bar the kick plays 1 and 3. Line 1 plays eighths on the snare and the high tom, then one beat of roll on the floor tom into the crash.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Toms are softer than a snare: press a little more for an even roll. Line 2 rolls on the mid tom and the floor tom, line 4 breaks the roll with an accented release on the high tom and again on the floor tom, line 7 rolls the whole bar and moves one tom down every beat. Line 8 plays doubles on the floor tom and ends with single thirty-seconds on the snare. Toms accept any tom and the crash any crash, so a kit with fewer drums plays the sheet too: the mid tom and the second floor tom go to the nearest tom you have.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "The roll into a chorus, big-band and show drumming, and the rolling tom fall at the end of rock ballads.",
  ),
];
